import React from 'react';
import { css } from '@emotion/css';
import { GrafanaTheme2 } from '@grafana/data';
import { useStyles2, Icon } from '@grafana/ui';
import { config } from '@grafana/runtime';
import { CustomDashboardListOptions } from '../types';

interface HeaderSectionProps {
  options: CustomDashboardListOptions;
  isAuthority: boolean;
  detectedRole?: 'authority' | 'operator' | 'admin';
  detectedAuthority?: string;
  detectedBetreiberkennzahl?: string;
  detectedUserName?: string;
  operatorName?: string;
  currentUsername?: string;
  isNarrow?: boolean;
}

export const HeaderSection: React.FC<HeaderSectionProps> = ({
  options,
  isAuthority,
  detectedRole,
  detectedAuthority,
  detectedBetreiberkennzahl,
  detectedUserName,
  operatorName,
  currentUsername,
  isNarrow = false,
}) => {
  const styles = useStyles2(getStyles);

  if (!options.header.showHeader) {
    return null;
  }

  const title = options.header.headerTitle;
  const isAdmin = detectedRole === 'admin';

  // Helper: check if a string is invalid as a person's display name
  const isInvalidName = (val?: string) => {
    if (!val) {
      return true;
    }
    const clean = val.replace(/['"]/g, '').trim();
    if (!clean) {
      return true;
    }
    // Pure numeric ID (e.g. "38", "47", "4110602600116")
    if (/^\d+$/.test(clean)) {
      return true;
    }
    // Unreplaced template variable (e.g. "${__user.name}", "${id}")
    if (clean.includes('${') || clean.includes('__user')) {
      return true;
    }
    return false;
  };

  const runtimeUserName = config?.bootData?.user?.name || config?.bootData?.user?.login;
  const rawOptionUser = (options.header.userName || '').trim();

  const validDetectedUser = !isInvalidName(detectedUserName) ? detectedUserName : undefined;
  const validOptionUser = !isInvalidName(rawOptionUser) ? rawOptionUser : undefined;
  const validRuntimeUser = !isInvalidName(runtimeUserName) ? runtimeUserName : undefined;

  // Final display name priority:
  // 1. Valid detected name from Query (e.g. o.name / au.name)
  // 2. If operator: real operator name from PostgreSQL rows (e.g. "Appelmann, Erhard")
  // 3. Current logged-in Grafana user from runtime session (e.g. "Administrator", "admin")
  // 4. Panel option user (if not a pure ID)
  // 5. Fallback: "Administrator" for admin, or "Benutzer"
  const displayUser =
    validDetectedUser ||
    (!isAuthority && operatorName ? operatorName : undefined) ||
    validRuntimeUser ||
    validOptionUser ||
    operatorName ||
    currentUsername ||
    (isAdmin ? 'Administrator' : 'Benutzer');

  const rawOptionAuth = (options.header.authorityName || '').trim();
  const validOptionAuth =
    rawOptionAuth && rawOptionAuth !== 'Zentrale Netzleitstelle' && !rawOptionAuth.includes('${')
      ? rawOptionAuth
      : undefined;
  const authority = detectedAuthority || validOptionAuth;

  const rawOptionBzk = (options.header.betreiberkennzahl || '').trim();
  const validOptionBzk =
    rawOptionBzk && rawOptionBzk !== 'OPS-DE-1044' && !rawOptionBzk.includes('${') ? rawOptionBzk : undefined;
  const bzk = detectedBetreiberkennzahl || validOptionBzk;

  // Determine whether to show authority name in parentheses:
  // - Show for Authorities: Willkommen Max Mustermann (Wasserwirtschaftsamt Aschaffenburg)
  // - Hide for Admins: Willkommen Max Mustermann
  const showAuthorityTag = isAuthority && !isAdmin && authority && authority !== 'All Authorities';

  return (
    <div className={styles.container}>
      {/* Header Title Banner - only shown if a custom title is explicitly given */}
      {title && title !== 'Smart Utility & Grid Operations' && (
        <div className={isNarrow ? styles.titleRowNarrow : styles.titleRow}>
          <div className={styles.titleGroup}>
            <div className={styles.titleTextWrapper}>
              <h1 className={isNarrow ? styles.mainTitleNarrow : styles.mainTitle}>{title}</h1>
            </div>
          </div>
        </div>
      )}

      {/* User Greeting Card matching exact layout specifications */}
      <div className={styles.welcomeCard}>
        <div className={styles.welcomeText}>
          {isAuthority ? (
            <div className={styles.greetingLine}>
              <span className={styles.welcomeTitle}>Willkommen {displayUser}</span>
              {showAuthorityTag && (
                <span className={styles.authorityTag}> ({authority})</span>
              )}
            </div>
          ) : (
            <div>
              <div className={styles.greetingLine}>
                <span className={styles.welcomeTitle}>Willkommen {displayUser}</span>
              </div>
              {bzk && (
                <div className={styles.bzkLine}>
                  <span className={styles.bzkLabel}>Betreiberkennzahl:</span>{' '}
                  <span className={styles.bzkValue}>{bzk}</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const getStyles = (theme: GrafanaTheme2) => ({
  container: css`
    display: flex;
    flex-direction: column;
    gap: ${theme.spacing(1)};
    margin-bottom: ${theme.spacing(1.5)};
  `,
  titleRow: css`
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: ${theme.spacing(1.5)};
    padding-bottom: ${theme.spacing(0.5)};
  `,
  titleRowNarrow: css`
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: ${theme.spacing(1)};
    padding-bottom: ${theme.spacing(0.5)};
  `,
  titleGroup: css`
    display: flex;
    align-items: center;
    gap: ${theme.spacing(1.5)};
    width: 100%;
    min-width: 0;
  `,
  titleTextWrapper: css`
    min-width: 0;
    flex: 1;
  `,
  mainTitle: css`
    margin: 0;
    font-size: ${theme.typography.h3.fontSize};
    font-weight: ${theme.typography.fontWeightBold};
    color: ${theme.colors.text.primary};
    line-height: 1.2;
    word-break: break-word;
  `,
  mainTitleNarrow: css`
    margin: 0;
    font-size: 18px;
    font-weight: ${theme.typography.fontWeightBold};
    color: ${theme.colors.text.primary};
    line-height: 1.25;
    word-break: break-word;
  `,
  welcomeCard: css`
    padding: ${theme.spacing(0.5)} 0;
    margin-bottom: ${theme.spacing(0.5)};
    display: inline-flex;
    flex-direction: column;
    border-right: 2px solid ${theme.colors.border.medium};
    padding-right: ${theme.spacing(3)};
  `,
  welcomeText: css`
    color: ${theme.colors.text.primary};
  `,
  greetingLine: css`
    line-height: 1.35;
    word-break: break-word;
  `,
  welcomeTitle: css`
    font-size: clamp(20px, 1.4vw, 26px);
    font-weight: ${theme.typography.fontWeightBold};
    color: ${theme.colors.text.primary};
  `,
  authorityTag: css`
    font-size: clamp(20px, 1.4vw, 26px);
    font-weight: ${theme.typography.fontWeightMedium};
    color: ${theme.colors.text.primary};
  `,
  bzkLine: css`
    margin-top: 6px;
    font-size: clamp(15px, 1vw, 18px);
    line-height: 1.4;
    color: ${theme.colors.text.primary};
  `,
  bzkLabel: css`
    font-weight: ${theme.typography.fontWeightBold};
    color: ${theme.colors.text.primary};
  `,
  bzkValue: css`
    font-weight: ${theme.typography.fontWeightRegular};
    color: ${theme.colors.text.primary};
  `,
});
